    ["02-10"] = {steps={[1]={npc="Xafetim Manigiro", tgt="Xafetim Manigiro"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Colete 6 Patas de Rastejante e coloque-as na Caixazorra 827."}, [5]={hint="Obtenha Ossos de Criaturas Marinhas da criatura marinha encalhada logo ao sul Auberdine e leve para Gwennyth Bly'Leggonde em Auberdine."}, [6]={npc="Caixazorra 827", npcObj=true}, [7]={npc="Caixazorra 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Leve 8 cargas de Minério de Elunita e o Medalhão de Elura para Elanaria em Darnassus."}, [11]={npc="Cerellean Garralva", tgt="Cerellean Garralva"}, [12]={hint="Recupere a Carcaça de Tartaruga Marinha da Tartaruga Marinha Descarnada nas águas a oeste de Auberdine, e então fale com Gwennyth Bly'Leggonde em Auberdine."}, [13]={hint="Recolha 3 Olhos de Mangual dos Manguais da Costa Negra no fundo do mar, perto da Caixazorra 411."}, [14]={text="Siga a estrada até este ponto."}, [15]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [16]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [17]={npc="Tharnariun Tratárvore", tgt="Tharnariun Tratárvore"}, [18]={npc="Terenthis", tgt="Terenthis"}, [19]={text="Siga a estrada até este ponto."}, [20]={hint="Capture um ursocardo raivoso e traga de volta para Tharnariun."}, [21]={hint="Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui."}, [22]={npc="Astérion", tgt="Astérion"}, [23]={npc="Astérion", tgt="Astérion"}, [24]={hint="Consiga 8 Brinco de Capeta para Astérion em Bashal'Aran."}, [25]={npc="Astérion", tgt="Astérion"}, [26]={npc="Astérion", tgt="Astérion"}, [27]={hint="Obtenha o Selo Antigo de Pedra-da-lua e leve-o para Astérion em Bashal'Aran."}, [28]={npc="Astérion", tgt="Astérion"}, [29]={npc="Astério