    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={text="Saia de Ventobravo e siga a estrada da Floresta de Elwynn para oeste, passe pela Vila d'Ouro e atravesse a ponte até Cerro Oeste; depois siga a estrada principal para o sul até o Morro da Sentinela.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [3]={npc="Delegado Ranieri", tgt="Delegado Ranieri"}, [4]={npc="Fazendeiro Taturana", tgt="Fazendeiro Taturana"}, [5]={npc="Vera Taturana", tgt="Vera Taturana"}, [6]={npc="Vera Taturana", tgt="Vera Taturana"}, [7]={hint="Vera Taturana quer que você leve 8 Punhados de Aveia para ela em Cerro Oeste.", tag="Opcional"}, [8]={npc="Fazendeiro Saldanha", tgt="Fazendeiro Saldanha"}, [9]={npc="Salma Saldanha", tgt="Salma Saldanha"}, [10]={npc="Ozwin Giroferro", tgt="Ozwin Giroferro"}, [11]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [12]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [13]={nodeA="{a:108}"}, [14]={npc="Batedor Galiaan", tgt="Batedor Galiaan"}, [15]={npc="Alba Belua", tgt="Alba Belua"}, [16]={npc="Alba Belua", tgt="Alba Belua"}, [17]={hint="Use o Kit de Amostras de Água de Poço para coletar amostras dos poços no Sítio dos Jansen e na Fazenda dos Peçanha."}, [18]={hint="O Fazendeiro Taturana quer que você recupere o relógio de bolso dele no guarda-roupa da sede de sua fazenda de abóboras, a oeste.", desc="Ajustando a câmera, dá para pegar de fora."}, [19]={hint="Alba Belua quer que você colete 7 Guelras de Murloc da Praia Grande ao longo da costa de Cerro Oeste."}, [20]={npc="Fazendeiro Taturana", tgt="Fazendeiro Taturana"}, [21]={hint="O Fazendeiro Saldanha quer que você mate 20 Guarda-colheitas."}, [22]={npc="Vera Taturana", tgt="Vera Taturana"}, [23]={npc="Fazendeiro Saldanha", tgt="Fazendeiro Saldanha"}, [24]={npc="Alba Belua", tgt="Alba Belua"}, [25]={npc="Alba Belua", tgt="Alba Belua"}, [26]={npc="Alba Belua", tgt="Alba Belua"}, [27]={hint="Mate 4 Escavadores Kobolds na Mina Veiojango e 6 Mineradores Pata Molhada na Pe