    ["05-d1"] = {name="Salão dos Thanes", entrance="Altaforja 27.63, 47.83", pickup="Ao passar por Dun Morogh e Loch Modan, pegue primeiro as missões pré-masmorra; não precisa voltar de propósito logo antes de entrar. Os Skyborne pulam a 01-parada 9: na primeira vez em Altaforja, vá para o leste, até Dun Morogh, procure o Vidente da Terra Farsen, faça Vigília de Farsen, Cortando o mal pela raiz e Mapa subterrâneo e volte para Altaforja. Se não quiser fazer o desvio, pule Incursão à Antiga Altaforja.", pickupS={{"Ao passar por Dun Morogh e Loch Modan, pegue primeiro as missões pré-masmorra; não precisa voltar de propósito logo antes de entrar"}, {"Os Skyborne pulam a 01-parada 9: na primeira vez em Altaforja, vá para o leste, até Dun Morogh, procure o Vidente da Terra Farsen, faça Vigília de Farsen, Cortando o mal pela raiz e Mapa subterrâneo e volte para Altaforja", {race={"天裔"}}}, {"Se não quiser fazer o desvio, pule Incursão à Antiga Altaforja"}}, steps={[1]={npc="Mapa Ferro Negro", npcObj=true, tag="Pré-requisito de masmorra"}, [2]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen", tag="Pré-requisito de masmorra"}, [3]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Entrada: Salão dos Thanes"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Mate 15 Aparições Enfurecidas, 10 Almas Atormentadas e dê descanso ao espírito de Sidermar."}, [10]={hint="Colete 8 Heranças Enânicas no Salão dos Thanes."}, [11]={hint="Adentre o Salão dos Thanes abaixo da Antiga Altaforja e corte a cabeça de Durgen Martelúgubre."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Clique com o botão direito em Tratado de Entendimento na bolsa para aceitar a missão. O chefe final usa Medo com cerca de 35% de vida. Limpe os lacaios primeiro e depois puxe o chefe para a sala anterior. Ao lado de quem dá a missão há uma alavanca. Puxe para abrir a porta e saia em linha reta."}, [13]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [14]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [15]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}, [16]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}}},
    ["02-12"] = {steps={[1]={npc="Grif Trovino", tgt="Grif Trovino"}, [2]={node="Altaforja"}, [4]={text="Saia de Altaforja e siga a estrada para leste, atravesse o túnel da passagem oriental até Loch Modan e depois siga a estrada para nordeste até Thelsamar.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [5]={nodeA="{a:144}"}, [6]={hint="O Montanhista Cascalhaça, da torre de guarda sul, quer que você mate 10 Batecrânios Lascapedra e 10 Videntes Lascapedra e fale novamente com ele."}, [7]={npc="Montanhista Cascalhaça", tgt="Montanhista Cascalhaça"}, [8]={npc="Montanhista Batemuro", tgt="Montanhista Batemuro"}, [9]={hint="Leve o Símbolo da Vida e ressuscite Narm Faulk em Dun Morogh."}, [10]={npc="Jern Elmocorno", tgt="Jern Elmocorno"}, [11]={npc="Brock Buscapedra", tgt="Brock Buscapedra"}, [12]={npc="Magmar Machadeiro", tgt="Magmar Machadeiro"}, [13]={npc="Magmar Machadeiro", tgt="Magmar Machadeiro"}, [14]={npc="Prospector Bandaferro", tgt="Prospector Bandaferro"}, [15]={npc="Dário, o Novato", tgt="Dário, o Novato"}, [16]={hint="Mate 6 Urubus Montanheses e fale novamente com Dário, o Novato, no Pavilhão dos Andarilhos, dentro de 15 minutos."}, [17]={npc="Dário, o Novato", tgt="Dário, o Novato"}, [18]={npc="Dário, o Novato", tgt="Dário, o Novato"}, [19]={hint="Mate 5 Javalis Montanheses Anciãos e fale novamente com Dário, o Novato, no Pavilhão dos Andarilhos, dentro de 12 minutos."}, [20]={npc="Dário, o Novato", tgt="Dário, o Novato"}, [21]={npc="Marek Ferrocordis", tgt="Marek Ferrocordis"}, [22]={npc="Marek Ferrocordis", tgt="Marek Ferrocordis"}, [23]={npc="Gomez Plosivo", tgt="Gomez Plosivo"}, [24]={npc="Gomez Plosivo", tgt="Gomez Plosivo"}, [25]={hint="Encontre e derrote o crocolisco Presadaga e traga de volta a faca de Marek."}, [26]={hint="Obtenha 5 peças de Carne de Crocolisco e 6 Peles de Crocolisco para Marek Ferrocordis no Pavilhão dos Andarilhos."}, [27]={hint="Encontre e devolva os suprimentos do Gomez:"}, [28]={hint="Montanhista Bat