pc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus"}, [57]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [58]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [59]={hint="Use o Coletor Vazio das Quedas de Fontescarpa para coletar uma amostra de água da entrada da caverna da cachoeira.", desc="Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran e depois voe para Auberdine."}, [60]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto"}, [61]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine."}, [62]={hint="Leve 5 Raízes-telúricas e 12 Fungos Lunares para Alanndária Noturcanto em Auberdine para que ela possa preparar o bálsamo curativo.", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine."}, [63]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine."}, [64]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Use o remédio nos cervos doentes da Costa Negra."}, [65]={hint="Use o Bálsamo Curativo para Animais em 10 Cervos Adoentados espalhados pela Costa Negra. Isso deve curá-los. Cervos Adoentados foram avistados da região ao sul do Rio Fontescarpa, seguindo até a área ao norte de Auberdine, até a Costa Negra meridional, na fronteira do Vale Gris.", desc="Use o remédio nos cervos doentes da Costa Negra."}, [66]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Depois de curar 10 cervos, use Teleporte: Clareira da Lua para voltar e entregar."}, [67]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Entregue a missão para aprender Curar Veneno."}, [68]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus", desc="Entregue a missão para aprender Curar Veneno. Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran e use o portal da vila para entrar em Darnassus."}, [69]