    ["03-29"] = {steps={[1]={tag="Opcional", desc="Pouca experiência no trecho de Darnassus. Pule se estiver com pressa."}, [2]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus.", tag="Opcional"}, [3]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [4]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [5]={hint="Vasculhe o baú de Velinde atrás do seu diário, depois leve-o junto com a chave para Thyn'tel Tecelâmina em Darnassus.", tag="Opcional"}, [6]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [7]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [8]={text="Entre no portal de Darnassus para voltar à Vila de Rut'theran.", tag="Opcional"}, [9]={text="Se fez as missões opcionais de Darnassus, voe da Vila de Rut'theran para Vila Catraca (com escalas em Auberdine e Talrendis Point); se pulou, voe de Astranaar (com escala em Talrendis Point). Siga a estrada principal para o sul, contorne o Acampamento Taurajo e desça para Mil Agulhas pelo Grande Elevador. Só use a Muralha de Mor'shan se nenhum dos dois pontos estiver descoberto."}, [10]={text="Siga a estrada até este ponto."}, [11]={nodeA="{a:489}"}, [12]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [13]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [14]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [15]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [16]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [17]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [18]={npc="Relé", tgt="Relé"}, [19]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [20]={hint="Obtenha 10 Ossos Ocos de Abutre para Relé no Salar Cintilante."}, [21]={hint="Mate 10 Basiliscos Sal-gema, 10 Cristaldermes Sal-gema e 6 Observadores Sal-gema para o Mestre de Pistas Zheran no Salar Cintilante."}, [22]={hint="Leve 9 Cascos Endurecidos de Tartaruga para Capu Latafuso no Salar Cintilante."}, [23]={hint="Leve 30 Peças de Carro-foguete para Kravel Barbakarvão no Salar Cintilante."}, [24]={hint="Leve 6 Peçonhas Salgadas de Escorpídeo para Xabu Latafuso no Salar Cintilante."}, [25]={npc="Relé", tgt="Relé"}, [26]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [27]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [28]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [29]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [30]={text="Das Planícies Brilhantes, siga a estrada para o sul até Tanaris, libere o ponto de voo de Geringontzan e depois use a pedra de regresso.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [31]={nodeA="{a:976}"}, [32]={}}},
    ["03-30"] = {name="Planalto Arathi", steps={[1]={desc="Se a Ponta do Refúgio não estiver liberada, voe até Porto de Menethil, siga a estrada para nordeste pelo Pantanal, atravesse a Ponte Thandol até o Planalto Arathi e depois siga a estrada até a Ponta do Refúgio."}, [2]={npc="Capitã Nélia", tgt="Capitã Nélia"}, [3]={npc="Capitã Nélia", tgt="Capitã Nélia", desc="Entregue a Demar Brant na Bastilha de Ermoforte, em Sendas do Rio; você vai lá na próxima parada."}, [4]={npc="Quadro de Procurados", npcObj=true, tag="Opcional"}, [5]={npc="Quadro de Procurados", npcObj=true, tag="Opcional"}, [6]={npc="Rodapeh", tgt="Rodapeh"}, [7]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten"}, [8]={npc="Estilhaços de Myzrael", npcObj=true}, [9]={hint="Colete 12 Grânulos of Myzrael, depois leve-os até os Fragmentos Iridescentes, em Garganta Seca."}, [10]={npc="Fragmentos Iridescentes", npcObj=true}, [11]={desc="Upe até uns três quartos do nível 36."}, [12]={npc="Fragmentos Iridescentes", npcObj=true}, [13]={hint="Consiga a Chave Ardente, a Chave Troante e a Chave Trovejante nas Pedras da União Ocidental, da União Oriental e de União Exterior."}, [14]={npc="Quae", tgt="Quae"}, [15]={npc="Quae", tgt="Quae"}, [16]={hint="Obtenha 10 Presas de Cascasseca, 4 Bolsas Medicinais de Cascasseca e uma Faca de Caçador Sombrio para o Aprendiz Kraiten, que aguarda na Ponta do Refúgio.", desc="Cuidado com a Mensageira Renegada que patrulha."}, [17]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten"}, [18]={npc="Rodapeh", tgt="Rodapeh"}, [19]={hint="Encontre a Varinha de Evocação de Trelane e entregue-a a Rodapeh, na Ponta do Refúgio."}, [21]={npc="Rodapeh", tgt="Rodapeh"}, [22]={npc="Rodapeh", tgt="Rodapeh", tag="Opcional"}, [23]={hint="Mate 10 Bandoleiros da Camarilha e 6 Mercenários da Camarilha."}, [24]={npc="Capitã Nélia", tgt="Capitã Nélia"}, [25]={npc="Capitã Nélia", tgt="Capitã Nélia", tag="Opcional"}, [26]={npc="Pedra de Vínculo Interior", npcObj=true}, [27]={hint="Entregue a Cabeça de Marez p