    ["04-45"] = {steps={[1]={npc="Sigrun Derrubaferro", tgt="Sigrun Derrubaferro", tag="Opcional", desc="Pelo caminho, você costuma conseguir Encantamentos de Labareda Abrasadora. Se não cair nenhum, abandone."}, [2]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional", desc="É preciso matar dois dracos negros elite de nível 50; pule se não tiver grupo."}, [3]={hint="Use o Signo da Terra para ativar os Pilares de Ametista, Opala e Diamante, e obter as Pedras Rúnicas.", tag="Faça depois, quando passar por lá, Grupo recomendado, Opcional"}, [4]={npc="Selo da Terra", npcObj=true, tag="Grupo recomendado, Opcional"}, [5]={npc="Selo da Terra", npcObj=true, tag="Grupo recomendado, Opcional"}, [6]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional"}, [7]={npc="Sigrun Derrubaferro", tgt="Sigrun Derrubaferro", tag="Opcional"}, [8]={hint="Mate o Embaixador Infernus na Fortaleza Angor e leve a prova de sua morte para o Conselheiro Belgrum em Altaforja."}, [9]={text="Das Ermos, vá para oeste e entre na Garganta Abrasadora pela trilha da montanha ao lado do acampamento da Horda em Karrath. Contorne Karrath.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [10]={npc="Banheiro de Madeira", npcObj=true}, [11]={hint="Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora."}, [12]={text="Mate Margol, a Enfurecida, para ganhar muita experiência.", tag="Opcional", desc="O Chifre de Margol abre a linha de missões da Chave da Garganta Abrasadora; se não for fazer, pule as etapas 13, 32-33, 35, 37 e 40-42 e, na etapa 43, voe de Altaforja de volta a Posto de Tório."}, [13]={npc="Chifre de Margol", npcObj=true, tag="Opcional", desc="Clique com o botão direito em Chifre de Margol na bolsa para iniciar a missão."}, [14]={npc="Banheiro de Madeira", npcObj=true}, [15]={npc="Banheiro de Madeira", npcObj=true}, [16]={hint="Pegue a cópia do Livro-Caixa de Rugov A. Massoaço e encontre os itens li