    ["04-55"] = {steps={[1]={desc="Se já liberou o Acampamento Ventogelante, voe direto e pule o próximo passo. Se o Ninho da Águia não estiver no seu mapa de voo, voe até Costa Sul e corra para leste até o Ninho da Águia pelo mesmo caminho da visita às Terras Agrestes."}, [2]={text="Do Ninho da Águia, siga a trilha da montanha para o norte até o canto sudeste das Terras Pestilentas Ocidentais (65.30, 86.80) e depois siga a estrada para o oeste até o Acampamento Ventogelante.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [3]={nodeA="{a:3197}"}, [4]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [5]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [6]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [7]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [8]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [9]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida", desc="Missão de entrega de uma carta; entregue perto da entrada do Monte Hyjal."}, [10]={npc="Flint Umbramais", tgt="Flint Umbramais"}, [11]={npc="Flint Umbramais", tgt="Flint Umbramais", tag="Opcional"}, [12]={hint="Mate 10 Esfoladores Descarnados e 10 Carniçais Salivantes na Colina do Pesar."}, [13]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [14]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [15]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [16]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [17]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [18]={hint="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la."}, [19]={hint="Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar 