    ["04-56"] = {steps={[1]={text="Do Ninho da Águia, siga a trilha da montanha para o norte até as Terras Pestilentas Ocidentais e depois vá para leste, atravessando o Rio Thondroril, até as Terras Pestilentas Orientais. Tirion Fordring está na cabana ao lado da entrada."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída."}, [6]={hint="Mate 30 Quirópragos e fale novamente com Tirion Fordring."}, [7]={hint="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro."}, [8]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [9]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [10]={hint="Encontre a boneca de Pâmela.", desc="Nas casas em ruínas da Vila das Flechas, pegue a cabeça, o lado esquerdo e o lado direito e clique com o botão direito para juntar."}, [11]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [12]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [13]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [14]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff"}, [15]={node="Capela Esperança da Luz"}, [16]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [17]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}, [18]={npc="Zelador Alen", tgt="Zelador Alen"}, [19]={hint="Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [21]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [22]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [23]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [24]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [25]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [26]={hint="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo."}, [27]={hint="Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz."}, [28]={npc="Pergaminho Rasgado", npcObj=true}, [29]={hint="Vasculhe as Terras Pestilentas Orientais em busca de pistas sobre o \"Arauto da Praga\" e os agentes da AVIN desaparecidos. Ser encontrar alguma Insígnia da AVIN, leve de volta para Flint Umbramais, no Acampamento Ventogelante.", tag="Opcional"}, [30]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [31]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [32]={npc="Zelador Alen", tgt="Zelador Alen"}, [33]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}}},
    ["04-53"] = {steps={[1]={desc="Você fará uma conexão no Acampamento Ventogelante ou no Ninho da Águia; se Costa Sul não estiver no seu mapa de voo, voe para Ventobravo como de costume e pegue o barco para Auberdine no porto."}, [2]={desc="No cais de Costa Sul há um barco direto para Auberdine, mais rápido do que voar para Ventobravo e trocar de barco. Se voar para Ventobravo, embarque no porto de Ventobravo."}, [4]={hint="Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos."}, [5]={hint="Salfa quer que você mate 8 Xamãs Invernosos, 8 Vigias do Covil dos Invernosos e 8 Ursinos Invernosos. Salfa está perto da entrada do Domínio dos Presamatos, em Hibérnia.", tag="Verificar no jogo"}, [6]={npc="Frasco Vazio de Aguardente", npcObj=true, desc="Clique com o botão direito em Frasco Vazio de Aguardente na bolsa para iniciar a missão."}, [7]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [8]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [9]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [10]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [11]={npc="Bruna Covaneve", tgt="Bruna Covaneve", desc="Explorar a Garganta do Sussurro Sombrio é concluído no caminho para o Monte Hyjal na próxima parada; entregue antes de voltar a Hibérnia e seguir para Clareira da Lua. Entregue antes de voltar a Hibérnia e seguir para Clareira da Lua."}, [12]={hint="Colete 10 Penas Lunamarca de Hibérnia, depois fale novamente com Erelas Ambarcéu, na Vila de Rut'theran."}, [13]={npc="Salfa", tgt="Salfa", tag="Verificar no jogo"}, [14]={npc="Caldeirão de Lenha Morta", npcObj=true}, [15]={npc="Caldeirão de Lenha Morta", npcObj=true}, [16]={desc="Do Caldeirão de Lenha Morta, vá para o sul até o ponto de voo de Talonbranch Glade (62.49, 24.24) e decole de lá; você faz escala em Auberdine."}, [17]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [18]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [19]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [21]={npc="Harlo Balançante", tgt="Harlo Balançante"}, [22]={npc="Eol Correnoite", tgt="Eol Correnoite"}, [23]={npc="Eol Correnoite", tgt="Eol Correnoite"}, [24]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [25]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [26]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [27]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [28]={hint="Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais."}, [29]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [30]={npc="Caixote Danificado", npcObj=true}, [31]={npc="Caixote Danificado", npcObj=true}, [32]={npc="Carroça de Jaron", npcObj=true}, [33]={npc="Carroça de Jaron", npcObj=true}, [34]={hint="Pegue os Suprimentos do Jaron na neve, depois encontre o coruscante que roubou o amuleto de que Jaron falou."}, [35]={npc="Ranshalla", tgt="Ranshalla"}, [36]={npc="Ranshalla", tgt="Ranshalla"}, [37]={hint="Proteja Ranshalla enquanto ela tenta reativar o Altar de Eluna. Relate suas descobertas a Erelas Ambarcéu, na Vila de Rut'theran."}}},
    ["04-57"] = {danger={[1]="Ghansurok (quimera elite de nível 61) patrulha dos hibiscos contaminados até a oficina de Kaylaena (cerca de x55-62,5, y61,5-72,2); confira a posição ao atacar os arbustos e ao voltar à oficina.", [2]="Celastrus, o Amargo (elite de nível 57), anda pelos hibiscos contaminados; fique atento ao atacar os arbustos.", [3]="A pilha de ossos invoca uma gosma elite de nível 58; sem grupo, não clique uma segunda vez."}, grind={[1]={note="A parte norte da Cicatriz de Sangue Vil; todas as missões de Felflick são feitas aqui."}}, supply={[1]={}}, steps={[1]={text="De Ranshalla vá ao sul para a Garganta do Sussurro Sombrio e siga o desfiladeiro a oeste até o fim para entrar no Monte Hyjal. Há um gigante de gelo elite na entrada e demônios elite lá dentro; fique na estrada e não pare.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé, Verificar no jogo"}, [2]={hint="Siga as instruções de Bruna Covaneve, depois fale novamente com ela.", tag="Verificar no jogo", desc="É concluída ao atravessar o desfiladeiro rumo ao Monte Hyjal; não precisa de desvio extra. Conta assim que o diário de missões a mostrar como concluída."}, [3]={text="Entre no Monte Hyjal pelo canto sudeste e siga a estrada para o oeste.", tag="Verificar no jogo"}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="Uma engrenagem no chão ao lado da estrada; clique com o botão direito para pegá-la e aceitar a missão."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Opcional", desc="Só entregue se tiver aceitado esta missão antes em Selva Maleva."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Saque de: Hyjal Stag, Predatory Hyjal Stag"}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", tag="Verificar no jogo", desc="Os destroços da balista, da catapulta e da máquina voadora contam como um objetivo cada, e é preciso plantar nos três. Procure na encosta fora da Caverna do Eremita."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine.", tag="Verificar no jogo", desc="As coordenadas são a localização aproximada informada pelos jogadores."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", desc="Siga a estrada para o oeste; o ponto de voo fica ao lado do posto dos anciões."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional", desc="O alvo é uma elite de nível 57; se não conseguir derrotá-lo sozinho, não aceite."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Quando for a Visteterna mais tarde, procure Nami para pegar as peças."}, [36]={hint="Matar: Tainted Shrubbery", desc="Os mesmos hibiscos também dropam as folhas que estancam sangramento; ataque-os para as duas missões juntas. Entregue na oficina quando levar a caixa."}, [37]={hint="Saque de: Tainted Shrubbery"}, [38]={hint="Saque de: Celastrus the Bitter", tag="Grupo recomendado, Opcional"}, [39]={npc="Hyacinth", tgt="Hyacinth"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Matar: Fraxinus"}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional", desc="O alvo, Sunderbark, é um ancião elite de nível 56; faça quando tiver grupo. Se não tiver grupo, pule as etapas \"The Dying Ancients\", \"The Dying Ancients\", \"The Dying Ancients\"."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Matar: Ashen Acolyte", desc="As anotações caem dos mesmos acólitos; enfrente-os para as duas missões."}, [53]={hint="Saque de: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Felflick", tgt="Felflick"}, [58]={npc="Felflick", tgt="Felflick"}, [59]={npc="Felflick", tgt="Felflick"}, [60]={hint="Saque de: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [61]={hint="Matar: Brashann Grimdark"}, [62]={npc="Felflick", tgt="Felflick"}, [63]={npc="Felflick", tgt="Felflick"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Bone Pile", npcObj=true, desc="Jogue os ossos do bruxo na pilha de ossos ao lado da poça de gosma."}, [66]={npc="Bone Pile", npcObj=true, tag="Grupo recomendado, Opcional", desc="Invoca uma gosma elite de nível 58. Se não tiver grupo, pule as etapas \"Amalgamated Marrow\"-\"Amalgamated Marrow\", \"Amalgamated Marrow\"-\"A Revenge Now Bitter\", \"A Revenge Now Bitter\"."}, [67]={hint="Matar: Awakened Fel Ash Slime", tag="Grupo recomendado, Opcional"}, [68]={npc="Velician", tgt="Velician"}, [69]={npc="Felflick", tgt="Felflick", tag="Grupo recomendado, Opcional"}, [70]={npc="Felflick", 