    [3883] = {n="Ecologia forânea", d="Use a Ampola de Amostra para coletar uma Amostra de Parede de Colmeia de uma das incubadoras Gorishi na Cratera Un'Goro. Procure as câmaras com larvas.\nLeve a Amostra de Parede de Colmeia para Hol'anyee Marshal na Cratera Un'Goro.", objs={"Gorishi Hive Hatchery"}},
