    [91688] = {n="To the Summit of Eternity", d="Travel to the Summit of Eternity and speak with the druids about the survivor village."},
    [91696] = {n="Open Season", d="Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow."},
    [91697] = {n="Meet the Elders", d="Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow."},
    [91698] = {n="Barkskin Breakout", d="Saque de: Deadwood Warden", tgo={{"Deadwood Warden"}}},
