    [91952] = {n="The Source of the Corruption", d="Find the hermit Ketharas on Mount Hyjal."},
    [92008] = {n="Premiere Parts", d="Retrieve Kaylaena Springbolt's parts order from Nami in Everlook."},
    [92009] = {n="Crate Expectations", d="Gently transport the crate of parts and baubles to Kaylaena Springwhisper in Mount Hyjal."},
    [92011] = {n="Rubble Rummage", d="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."},
